rows=[];meta=set();data=[json.loads(s) for s in (P/'banglabbq_health_status_english.jsonl').open()];src={f'Q{x["question_index"]:02d}':x['additional_metadata']['source'] for x in data}
audit={x['theme_id']:x for x in csv.DictReader((P/'banglabbq_health_status_source_audit.csv').open(encoding='utf-8-sig'))}
for q,r in audit.items():
 for k in ('source_1_url','source_2_url'):
  if r.get(k):meta.add(r[k]);assert r[k] in [s[0] for s in DATA]
 assert src[q]==r['source_1_url'], (q,src[q],r['source_1_url'])
fields=['URL','covered_themes','in_additional_metadata','in_source_audit','verified_title_publisher','publication_date','read_access_status','supported_finding','correspondence_to_theme','limitations','retrieved_date','is_source_proof_of_fictional_event','human_verified']
with (P/'health_status_source_url_audit.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for u,title,date,access,finding,fit,limit in DATA:
  themes=sorted(q for q,r in audit.items() if u in (r['source_1_url'],r.get('source_2_url','')))
  assert themes,(u,'URL not in source list')
  w.writerow(dict(URL=u,covered_themes=';'.join(themes),in_additional_metadata='YES' if u in src.values() else 'NO',in_source_audit='YES',verified_title_publisher=title,publication_date=date,read_access_status=access,supported_finding=finding,correspondence_to_theme=fit,limitations=limit,retrieved_date='2026-10-26',is_source_proof_of_fictional_event='NO',human_verified='NO'))
print('verified URLs',len(DATA),'all cited urls',len(meta),'Q1-Q10 metadata',len(src))
